import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Employees — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Employees — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/employees"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Employees — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/employees"}]]},"headers":[],"relativePath":"user-guide/employees.md","filePath":"user-guide/employees.md","lastUpdated":1787698014000}'),n={name:"user-guide/employees.md"};function s(l,e,i,d,m,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="employees-—-user-guide" tabindex="-1">Employees — User Guide <a class="header-anchor" href="#employees-—-user-guide" aria-label="Permalink to &quot;Employees — User Guide&quot;">​</a></h1><h2 id="who-can-use-employees" tabindex="-1">Who can use Employees <a class="header-anchor" href="#who-can-use-employees" aria-label="Permalink to &quot;Who can use Employees&quot;">​</a></h2><p>Your workspace must have the <strong>Employees</strong> module installed. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code> as needed).</p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Employees</strong> from the sidebar, under the <strong>HR</strong> group.</p><ul><li>Search by name, employee number, email, phone, job title, or department</li><li>Filter by status (Active / Inactive / Terminated) and employment type</li><li>KPI cards summarize total, active, inactive, and terminated headcount</li><li>Users with <strong>restore</strong> can filter trash, then <strong>Restore</strong> or permanently delete</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New employee</strong></li><li>Enter employee number and name (required); optionally email, phone, job title, department, hire/termination dates, employment type, status, linked user, and notes</li><li>Save</li></ol><p>When the <strong>Departments</strong> module is installed, the free-text Department field is replaced by a multi-select of departments (synced via <code>department_ids</code>).</p><p>Edit from the row menu or the employee record page.</p><h2 id="convert-from-users" tabindex="-1">Convert from Users <a class="header-anchor" href="#convert-from-users" aria-label="Permalink to &quot;Convert from Users&quot;">​</a></h2><p>If someone already has a workspace login but no Employees directory row (common when Users were created before you installed Employees):</p><ol><li>Open <strong>Administration → Users</strong></li><li>Row menu → <strong>Create employee record</strong> (requires <code>employees.create</code>)</li><li>Confirm — the platform creates a linked employee (name/email from the user, next <code>EMP-####</code> number)</li></ol><p>You can also create an employee manually and pick the <strong>Linked user</strong> on the employee form. Salary is configured later under <strong>Payroll → Profiles</strong>, not on the employee record.</p><h2 id="status-employment-type" tabindex="-1">Status &amp; employment type <a class="header-anchor" href="#status-employment-type" aria-label="Permalink to &quot;Status &amp; employment type&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Values</th></tr></thead><tbody><tr><td>Status</td><td>Active, Inactive, Terminated</td></tr><tr><td>Employment type</td><td>Full time, Part time, Contract</td></tr></tbody></table><p>Terminated employees remain in the directory for history; leave, attendance, and payroll continue to reference them by id.</p><h2 id="related-modules" tabindex="-1">Related modules <a class="header-anchor" href="#related-modules" aria-label="Permalink to &quot;Related modules&quot;">​</a></h2><p>Install <strong>Leave Management</strong>, <strong>Attendance</strong>, and <strong>Payroll</strong> from Marketplace (each requires Employees) for leave workflows, daily presence, and pay runs.</p>',19)])])}const h=t(n,[["render",s]]);export{u as __pageData,h as default};
